CREATE TABLE public.observatory_verticals (slug text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.observatory_verticals TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.observatory_verticals TO authenticated;
GRANT ALL ON public.observatory_verticals TO service_role;
ALTER TABLE public.observatory_verticals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public editorial verticals" ON public.observatory_verticals FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Ops maintain verticals" ON public.observatory_verticals FOR ALL TO authenticated USING (public.has_ops_write(auth.uid())) WITH CHECK (public.has_ops_write(auth.uid()));
CREATE TABLE public.observatory_keywords (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vertical_slug text NOT NULL REFERENCES public.observatory_verticals(slug) ON DELETE CASCADE, keyword text NOT NULL, scope text NOT NULL DEFAULT 'Todos', UNIQUE(vertical_slug, keyword));
GRANT SELECT ON public.observatory_keywords TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.observatory_keywords TO authenticated;
GRANT ALL ON public.observatory_keywords TO service_role;
ALTER TABLE public.observatory_keywords ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public editorial keywords" ON public.observatory_keywords FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Ops maintain keywords" ON public.observatory_keywords FOR ALL TO authenticated USING (public.has_ops_write(auth.uid())) WITH CHECK (public.has_ops_write(auth.uid()));
CREATE TABLE public.observatory_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vertical_slug text NOT NULL REFERENCES public.observatory_verticals(slug), title text NOT NULL, source_name text NOT NULL, source_url text NOT NULL UNIQUE, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), summary text NOT NULL, content_angle text NOT NULL, hook text NOT NULL, relevance integer NOT NULL DEFAULT 50 CHECK (relevance BETWEEN 0 AND 100), geographic_scope text NOT NULL CHECK (geographic_scope IN ('México/LatAm','Global')), channel text NOT NULL DEFAULT 'Medios', is_milestone boolean NOT NULL DEFAULT false, key_fact text NOT NULL DEFAULT '', why_it_matters text NOT NULL DEFAULT '', insights jsonb NOT NULL DEFAULT '[]', is_reference boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.observatory_signals TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.observatory_signals TO authenticated;
GRANT ALL ON public.observatory_signals TO service_role;
ALTER TABLE public.observatory_signals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public editorial signals" ON public.observatory_signals FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Ops maintain signals" ON public.observatory_signals FOR ALL TO authenticated USING (public.has_ops_write(auth.uid())) WITH CHECK (public.has_ops_write(auth.uid()));
CREATE INDEX observatory_signals_vertical_date ON public.observatory_signals(vertical_slug, published_at DESC);
COMMENT ON TABLE public.observatory_signals IS 'Public editorial references only; never store private client or personal data here.';